insert  into `t_article`(`id`,`title`,`category`,`cover`,`summary`,`content`,`view_count`,`status`,`create_time`,`update_time`) values 
(1,'春季如何预防感冒','疾病预防',NULL,'春季是感冒高发季节，注意保暖和卫生','春季气温变化大，容易引发感冒。建议：1.注意增减衣物 2.勤洗手 3.保持室内通风 4.均衡饮食 5.适当运动增强免疫力。',156,1,'2026-08-12 07:52:03','2026-08-12 07:52:03'),
(2,'高血压患者的饮食指南','慢性病管理',NULL,'合理饮食对控制血压至关重要','高血压患者应低盐饮食，每日盐摄入量不超过6克。多吃蔬菜水果，限制高脂肪食物，适量摄入优质蛋白。',234,1,'2026-08-12 07:52:03','2026-08-12 07:52:03'),
(3,'糖尿病日常管理要点','慢性病管理',NULL,'血糖控制需要综合管理','糖尿病患者需定期监测血糖，按时服药，控制饮食，坚持运动，定期复查。',189,1,'2026-08-12 07:52:03','2026-08-12 07:52:03'),
(4,'儿童发热家庭护理','儿科健康',NULL,'孩子发热时家长应如何应对','儿童发热时：1.测量体温 2.物理降温 3.适当补水 4.观察精神状态 5.必要时就医。',312,1,'2026-08-12 07:52:03','2026-08-12 07:52:03'),
(5,'合理运动与健康','健康生活',NULL,'运动是保持健康的重要方式','建议每周至少150分钟中等强度有氧运动，如快走、游泳、骑自行车等。',98,1,'2026-08-12 07:52:03','2026-08-12 07:52:03'),
(6,'心理健康的重要性','心理健康',NULL,'关注心理健康同样重要','保持积极心态，学会压力管理，必要时寻求专业心理咨询帮助。',145,1,'2026-08-12 07:52:03','2026-08-12 07:52:03'),
(7,'夏季防晒指南','皮肤健康',NULL,'紫外线防护不可忽视','外出时使用防晒霜，佩戴遮阳帽和太阳镜，避免在10-16点长时间暴晒。',167,1,'2026-08-12 07:52:03','2026-08-12 07:52:03'),
(8,'老年人营养补充','老年健康',NULL,'老年人特殊营养需求','老年人应保证蛋白质、钙、维生素D等营养素的充足摄入，预防骨质疏松。',79,1,'2026-08-12 07:52:03','2026-08-12 10:46:24'),
(9,'戒烟的健康益处','健康生活',NULL,'戒烟任何时候都不晚','戒烟后20分钟心率下降，2周 circulation改善，1年心脏病风险减半。',202,1,'2026-08-12 07:52:03','2026-08-12 10:46:21'),
(10,'睡眠与健康的关系','健康生活',NULL,'优质睡眠是健康基石','成年人建议每天7-8小时睡眠，保持规律作息，创造良好睡眠环境。',177,1,'2026-08-12 07:52:03','2026-08-12 10:46:19'),
(11,'胃病的预防与调理','消化健康',NULL,'保护胃部健康的方法','规律饮食，避免暴饮暴食，少吃辛辣刺激食物，戒烟限酒。',134,1,'2026-08-12 07:52:03','2026-08-12 07:52:03'),
(12,'眼睛保健常识','眼科健康',NULL,'日常护眼小贴士','避免长时间用眼，每40分钟休息10分钟，保持正确读写姿势。',89,1,'2026-08-12 07:52:03','2026-08-12 07:52:03'),
(13,'骨质疏松的预防','骨骼健康',NULL,'骨骼健康从年轻开始','补充钙和维生素D，适量运动，避免吸烟和过量饮酒。',113,1,'2026-08-12 07:52:03','2026-08-12 15:23:43'),
(14,'过敏季节的应对','过敏防治',NULL,'季节性过敏防护策略','了解过敏原，外出佩戴口罩，保持室内清洁，必要时使用抗过敏药物。',146,1,'2026-08-12 07:52:03','2026-08-12 10:46:17'),
(15,'Heart-healthy diet tips','心血管健康',NULL,'Protect your heart with food','Eat more fruits, vegetables, whole grains. Limit saturated fats and sodium.',67,1,'2026-08-12 07:52:03','2026-08-12 07:52:03'),
(16,' Vaccination importance','疾病预防',NULL,'疫苗接种保护健康','按时接种疫苗是预防传染病最有效的手段之一。',99,1,'2026-08-12 07:52:03','2026-08-12 10:46:15'),
(17,'Water intake guidelines','健康生活',NULL,'每日饮水量建议','成年人每天建议饮水1500-2000毫升，运动时适当增加。',157,1,'2026-08-12 07:52:03','2026-08-12 10:46:12'),
(18,'Stress management techniques','心理健康',NULL,'Effective ways to manage stress','Deep breathing, meditation, exercise, and hobbies can help reduce stress.',134,1,'2026-08-12 07:52:03','2026-08-12 07:52:03'),
(19,'Oral health care','口腔健康',NULL,'牙齿健康日常护理','每天刷牙两次，使用牙线，定期口腔检查。',89,1,'2026-08-12 07:52:03','2026-08-12 07:52:03'),
(20,'First aid basics','急救知识',NULL,'常见急救处理方法','掌握心肺复苏、止血包扎、烧烫伤处理等基本急救技能。',269,1,'2026-08-12 07:52:03','2026-08-12 10:48:57');

/*Table structure for table `t_consult_message` */

DROP TABLE IF EXISTS `t_consult_message`;

CREATE TABLE `t_consult_message` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `session_id` int NOT NULL COMMENT '会话ID',
  `role` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色:user/assistant',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容',
  `references_json` text COLLATE utf8mb4_unicode_ci COMMENT '引用来源JSON',
  `graph_json` text COLLATE utf8mb4_unicode_ci COMMENT '图谱实体JSON',
  `cost_time` int DEFAULT '0' COMMENT '耗时(毫秒)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI问诊消息表';

/*Data for the table `t_consult_message` */

insert  into `t_consult_message`(`id`,`session_id`,`role`,`content`,`references_json`,`graph_json`,`cost_time`,`create_time`) values 
(1,1,'user','最近经常头痛，是什么原因？',NULL,NULL,0,'2026-08-12 07:52:03'),
(2,1,'assistant','头痛可能由多种原因引起，如紧张性头痛、偏头痛、高血压等。建议注意休息，如持续不缓解请就医。',NULL,NULL,0,'2026-08-12 07:52:03'),
(3,2,'user','咳嗽已经持续一周了',NULL,NULL,0,'2026-08-12 07:52:03'),
(4,2,'assistant','持续咳嗽可能与上呼吸道感染、支气管炎等有关。建议多饮水，避免刺激性食物，必要时到呼吸内科就诊。',NULL,NULL,0,'2026-08-12 07:52:03'),
(5,4,'user','面部出现红疹，疑似过敏，啥情况？',NULL,NULL,0,'2026-08-12 09:48:53'),
(6,4,'assistant','您好！作为AI智能医疗问诊助手，以下建议仅供参考，**不能替代专业医生的面诊与诊断**。如您症状较重或持续不缓解，请及时前往医院就诊。\n\n### ? 关于参考知识库的说明\n您提供的参考文档主要涵盖**感冒/流感鉴别、高血压防治及糖尿病管理**，并未包含皮肤科或过敏性疾病的相关内容。以下建议基于临床常见诊疗路径为您梳理，供您初步参考：\n\n---\n\n### ? 面部红疹（疑似过敏）的常见原因\n1. **接触性过敏**：新换的护肤品、化妆品、洗面奶、面膜、口罩材质、染发剂等。\n2. **吸入/环境过敏**：花粉、尘螨、宠物皮屑、空气污染或紫外线照射。\n3. **食物或药物过敏**：近期食用海鲜、坚果、芒果等易致敏食物，或服用抗生素、解热镇痛药等。\n4. **其他需鉴别的皮肤病**：如玫瑰痤疮、脂溢性皮炎、接触性皮炎、带状疱疹早期等，需医生面诊区分。\n\n---\n\n### ? 初步应对建议\n- **立即停用可疑产品**：暂停所有新接触的面部护肤品/化妆品，改用温水或温和无皂基洁面产品清洁。\n- **避免刺激**：不要热水烫洗、不要搔抓或自行挤压，暂停去角质、刷酸、美容仪等操作。\n- **温和冷敷**：用干净毛巾包裹冷水或冰袋轻敷红肿处，每次10~15分钟，每日2~3次，可缓解瘙痒与灼热感。\n- **谨慎用药**：不建议自行购买含激素药膏涂抹面部，以免引发激素依赖性皮炎或掩盖病情。如需用药，请咨询医生或药师。\n\n---\n\n### ? 何时必须及时就医\n出现以下任一情况，请**立即前往皮肤科或急诊**：\n- 红疹迅速蔓延，伴面部/眼周/口唇明显肿胀\n- 出现呼吸困难、胸闷、声音嘶哑、吞咽困难或头晕（警惕严重过敏反应）\n- 皮疹出现水疱、渗出、结痂、剧烈疼痛或伴发热\n- 自行护理3~5天无改善，或反复发作影响生活\n\n---\n\n### ? 日常护理与预防\n- 近期饮食清淡，避免酒精、辛辣刺激及已知过敏食物。\n- 做好物理防晒（遮阳帽、口罩），选用成分简单、无香精酒精的医用保湿霜修复屏障。\n- 保持规律作息，避免熬夜与精神紧张，有助于免疫系统稳定。\n- 就诊时可携带近期使用过的护肤品清单或照片，便于医生排查过敏原。\n\n建议您尽快至正规医院**皮肤科**就诊，医生可通过面诊、斑贴试验或血清特异性IgE检测明确诱因，并规范开具抗组胺药或外用制剂。切勿盲目用药或听信偏方，以免延误病情。祝您早日恢复！','[{\"index\": 1, \"file_name\": \"感冒与流感指南.md\", \"content\": \"# 感冒与流感鉴别及处理\\n\\n## 普通感冒\\n由多种病毒（主要是鼻病毒）引起的上呼吸道感染。\\n\\n### 常见症状\\n- 鼻塞、流涕（清水样→粘稠）\\n- 咽痛、咳嗽\\n- 低热或无发热\\n- 全身症状较轻\\n\\n### 处理建议\\n- 休息、多饮水\\n- 对症用药：退热（体温>38.5°C）、止咳、缓解鼻塞\\n- 病程一般7-10天自愈\\n- 不推荐常规使用抗生素\\n\\n## 流行性感冒\\n由 influenza 病毒引起，\"}, {\"index\": 2, \"file_name\": \"高血压防治指南.md\", \"content\": \"# 高血压防治指南\\n\\n## 什么是高血压\\n高血压是指在未使用降压药物的情况下，非同日3次测量血压，收缩压≥140mmHg和/或舒张压≥90mmHg。\\n\\n## 常见症状\\n- 头痛，尤其是后脑勺部位\\n- 头晕、头胀\\n- 心悸、胸闷\\n- 疲劳、乏力\\n- 部分患者可无明显症状\\n\\n## 危险因素\\n1. 遗传因素\\n2. 高盐饮食\\n3. 肥胖\\n4. 缺乏运动\\n5. 长期精神紧张\\n6. 吸烟饮酒\\n\\n## 治疗原则\"}, {\"index\": 3, \"file_name\": \"糖尿病健康管理.md\", \"content\": \"# 糖尿病健康管理\\n\\n## 糖尿病概述\\n糖尿病是一组以高血糖为特征的代谢性疾病。主要分为1型糖尿病、2型糖尿病和妊娠糖尿病。\\n\\n## 典型症状（三多一少）\\n- 多饮：口渴明显，饮水量增多\\n- 多尿：尿量增多，夜尿频繁\\n- 多食：食欲亢进，容易饥饿\\n- 体重下降：不明原因体重减轻\\n\\n## 诊断标准\\n- 空腹血糖 ≥ 7.0 mmol/L\\n- 餐后2小时血糖 ≥ 11.1 mmol/L\\n- 糖化血红蛋\"}]','[]',33588,'2026-08-12 09:49:28')