/*Data for the table `t_knowledge_chunk` */

insert  into `t_knowledge_chunk`(`id`,`file_id`,`chunk_index`,`content`,`vector_id`,`create_time`) values 
(4,10,0,'# 感冒与流感鉴别及处理\n\n## 普通感冒\n由多种病毒（主要是鼻病毒）引起的上呼吸道感染。\n\n### 常见症状\n- 鼻塞、流涕（清水样→粘稠）\n- 咽痛、咳嗽\n- 低热或无发热\n- 全身症状较轻\n\n### 处理建议\n- 休息、多饮水\n- 对症用药：退热（体温>38.5°C）、止咳、缓解鼻塞\n- 病程一般7-10天自愈\n- 不推荐常规使用抗生素\n\n## 流行性感冒\n由 influenza 病毒引起，传染性强，全身症状重。\n\n### 常见症状\n- 突发高热（39-40°C）\n- 头痛、全身肌肉酸痛\n- 明显乏力\n- 咳嗽、咽痛\n\n### 处理建议\n- 48小时内可使用抗病毒药物（奥司韦）\n- 充分休息，隔离防护\n- 高热时使用退热药\n- 警惕并发症：肺炎、心肌炎\n\n## 何时就医\n- 高热持续超过3天\n- 呼吸困难或胸痛\n- 症状持续超过10天无好转\n- 出现严重头痛、意识改变','file_10_chunk_0','2026-08-12 07:54:14'),
(5,11,0,'# 糖尿病健康管理\n\n## 糖尿病概述\n糖尿病是一组以高血糖为特征的代谢性疾病。主要分为1型糖尿病、2型糖尿病和妊娠糖尿病。\n\n## 典型症状（三多一少）\n- 多饮：口渴明显，饮水量增多\n- 多尿：尿量增多，夜尿频繁\n- 多食：食欲亢进，容易饥饿\n- 体重下降：不明原因体重减轻\n\n## 诊断标准\n- 空腹血糖 ≥ 7.0 mmol/L\n- 餐后2小时血糖 ≥ 11.1 mmol/L\n- 糖化血红蛋白 ≥ 6.5%\n\n## 综合管理\n1. **饮食控制**：控制总热量，低GI饮食，定时定量\n2. **运动疗法**：每周至少150分钟中等强度运动\n3. **药物治疗**：口服降糖药或胰岛素\n4. **血糖监测**：定期检测空腹及餐后血糖\n5. **并发症筛查**：眼底、肾脏、足部检查\n\n## 急性并发症\n- 低血糖：出汗、心慌、饥饿感，需立即补充糖分\n- 酮症酸中毒：恶心、呕吐、呼吸深快，需紧急就医\n\n## 饮食建议\n推荐：粗粮、绿叶蔬菜、优质蛋白（鱼、豆制品）\n限制：精制碳水、含糖饮料、高糖水果','file_11_chunk_0','2026-08-12 07:54:14'),
(6,12,0,'# 高血压防治指南\n\n## 什么是高血压\n高血压是指在未使用降压药物的情况下，非同日3次测量血压，收缩压≥140mmHg和/或舒张压≥90mmHg。\n\n## 常见症状\n- 头痛，尤其是后脑勺部位\n- 头晕、头胀\n- 心悸、胸闷\n- 疲劳、乏力\n- 部分患者可无明显症状\n\n## 危险因素\n1. 遗传因素\n2. 高盐饮食\n3. 肥胖\n4. 缺乏运动\n5. 长期精神紧张\n6. 吸烟饮酒\n\n## 治疗原则\n- 生活方式干预：低盐饮食（每日<6g）、控制体重、规律运动\n- 药物治疗：钙通道阻滞剂、ACEI/ARB、利尿剂等\n- 定期监测血压\n- 目标血压：一般<140/90mmHg，合并糖尿病或肾病<130/80mmHg\n\n## 注意事项\n高血压是心脑血管疾病的主要危险因素，需要长期规范管理，不可自行停药。','file_12_chunk_0','2026-08-12 07:54:14'),
(7,13,0,'肺炎症状识别与诊疗方案\n一、疾病概述\n肺炎（Pneumonia）是指终末气道、肺泡和肺间质的炎症，可由多种病原微生物（细菌、病毒、真菌、寄生虫等）、理化因素、免疫损伤、过敏及药物等因素引起。其中感染性肺炎最为常见。\n肺炎是全球范围内导致死亡的重要感染性疾病，是5岁以下儿童死亡的首要原因，也是老年人住院和死亡的重要原因。全球每年约有4.5亿人罹患肺炎，约400万人死于肺炎。\n二、分类\n1. 按获得场所分类：\n- 社区获得性肺炎（CAP）：在医院外罹患的感染性肺实质炎症\n- 医院获得性肺炎（HAP）：入院48小时后发生的肺炎\n- 呼吸机相关性肺炎（VAP）：机械通气48小时后发生的肺炎\n- 医疗保健相关性肺炎（HCAP）\n2. 按病原体分类：\n- 细菌性肺炎：肺炎链球菌（最常见）、金黄色葡萄球菌、流感嗜血杆菌、肺炎克雷伯菌\n- 非典型病原体肺炎：肺炎支原体、肺炎衣原体、嗜肺军团菌\n- 病毒性肺炎：流感病毒、呼吸道合胞病毒、SARS-CoV-2\n- 真菌性肺炎：曲霉菌、隐球菌、肺孢子菌\n3. 按病理分类：\n- 大叶性肺炎\n- 小叶性肺炎（支气管肺炎）\n- 间质性肺炎\n三、临床症状\n典型症状：','file_13_chunk_0','2026-08-12 15:33:11'),
(8,13,1,'- 真菌性肺炎：曲霉菌、隐球菌、肺孢子菌\n3. 按病理分类：\n- 大叶性肺炎\n- 小叶性肺炎（支气管肺炎）\n- 间质性肺炎\n三、临床症状\n典型症状：\n1. 呼吸道症状：\n- 咳嗽：最常见症状，初为干咳，后可有痰\n- 咳痰：痰液性质因病原体不同而异\n  * 铁锈色痰：肺炎链球菌肺炎\n  * 砖红色胶冻样痰：肺炎克雷伯菌肺炎\n  * 黄绿色脓痰：金黄色葡萄球菌或铜绿假单胞菌\n  * 白色黏液痰：病毒性或支原体肺炎\n- 呼吸困难：中重症患者出现，表现为气促、呼吸频率增快\n- 胸痛：累及胸膜时出现，与呼吸运动有关的锐痛\n2. 全身症状：\n- 发热：多为高热（39-40°C），可伴寒战\n- 乏力、全身肌肉酸痛\n- 头痛\n- 食欲减退\n- 老年患者可无发热，仅表现为意识障碍、食欲下降\n3. 体征：\n- 呼吸频率增快（>20次/分）\n- 肺部叩诊浊音\n- 听诊：湿啰音、支气管呼吸音\n- 语颤增强\n四、诊断\n诊断标准（需同时满足）：\n1. 新出现的咳嗽、咳痰或原有呼吸道疾病症状加重，伴或不伴脓痰、胸痛、呼吸困难\n2. 发热\n3. 肺实变体征和/或听诊闻及湿啰音','file_13_chunk_1','2026-08-12 15:33:11'),
(9,13,2,'诊断标准（需同时满足）：\n1. 新出现的咳嗽、咳痰或原有呼吸道疾病症状加重，伴或不伴脓痰、胸痛、呼吸困难\n2. 发热\n3. 肺实变体征和/或听诊闻及湿啰音\n4. WBC>10×10⁹/L或<4×10⁹/L，伴或不伴核左移\n5. 胸部影像学检查显示片状、斑片状浸润性阴影或间质性改变\n第5条为必需条件，加上1-4条中任何一项即可诊断。\n辅助检查：\n1. 实验室检查：\n- 血常规：白细胞计数和分类\n- C反应蛋白（CRP）：细菌感染时显著升高\n- 降钙素原（PCT）：>0.25 μg/L提示细菌感染\n- 血气分析：评估氧合状态\n2. 病原学检查：\n- 痰培养和药敏试验\n- 血培养（重症患者）\n- 尿抗原检测（肺炎链球菌、军团菌）\n- 呼吸道病毒核酸检测\n- 支原体/衣原体抗体检测\n3. 影像学检查：\n- 胸部X线：首选检查\n- 胸部CT：敏感性更高，可发现早期或隐匿性病变\n严重程度评估工具：\n- CURB-65评分：意识障碍、尿素氮>7mmol/L、呼吸频率≥30次/分、血压<90/60mmHg、年龄≥65岁\n- 0-1分：门诊治疗；2分：考虑住院；3-5分：重症，考虑ICU\n五、治疗方案','file_13_chunk_2','2026-08-12 15:33:11'),
(10,13,3,'- 0-1分：门诊治疗；2分：考虑住院；3-5分：重症，考虑ICU\n五、治疗方案\n1. 经验性抗菌治疗：\n门诊患者（轻症CAP）：\n- 无基础疾病的青壮年：阿莫西林 1g 每日3次，或阿奇霉素 500mg 首日后250mg/日×4天\n- 有基础疾病或老年人：阿莫西林/克拉维酸 + 阿奇霉素，或呼吸喹诺酮类（莫西沙星、左氧氟沙星）\n住院患者（普通病房）：\n- β-内酰胺类（头孢曲松/头孢噻肟/氨苄西林舒巴坦）+ 大环内酯类（阿奇霉素）\n- 或呼吸喹诺酮类单药\n重症患者（ICU）：\n- β-内酰胺类 + 大环内酯类\n- 或β-内酰胺类 + 呼吸喹诺酮类\n- 怀疑MRSA：加用万古霉素或利奈唑胺\n- 怀疑铜绿假单胞菌：加用抗假单胞菌β-内酰胺类\n2. 支持治疗：\n- 氧疗：SpO2<90%时给予\n- 补液：纠正脱水和电解质紊乱\n- 退热：体温>38.5°C时使用退热药\n- 化痰：氨溴索、乙酰半胱氨酸\n- 营养支持\n3. 疗程：\n- 一般CAP：5-7天（症状改善后可停药）\n- 肺炎支原体/衣原体：10-14天\n- 军团菌肺炎：10-21天\n- 金黄色葡萄球菌肺炎：14-21天','file_13_chunk_3','2026-08-12 15:33:11'),
(11,13,4,'- 一般CAP：5-7天（症状改善后可停药）\n- 肺炎支原体/衣原体：10-14天\n- 军团菌肺炎：10-21天\n- 金黄色葡萄球菌肺炎：14-21天\n- 肺脓肿：4-6周\n六、预防措施\n1. 疫苗接种：\n- 肺炎球菌疫苗：65岁以上老年人、慢性病患者\n  * 23价多糖疫苗（PPV23）\n  * 13价结合疫苗（PCV13）\n- 流感疫苗：每年接种，减少流感继发肺炎\n- COVID-19疫苗\n2. 一般预防措施：\n- 保持良好手卫生\n- 避免密切接触呼吸道感染患者\n- 戒烟\n- 合理营养，增强免疫力\n- 治疗基础疾病\n- 避免误吸（老年人和卒中后患者）\n3. 院内肺炎预防：\n- 抬高床头30-45度\n- 口腔护理\n- 严格无菌操作\n- 合理使用镇静剂\n- 每日评估是否可撤机拔管','file_13_chunk_4','2026-08-12 15:33:11'),
(12,14,0,'# 冠状动脉粥样硬化性心脏病（冠心病）症状与诊疗\n\n## 一、疾病概述\n\n冠心病（Coronary Heart Disease, CHD）是由于冠状动脉粥样硬化导致血管腔狭窄或阻塞，引起心肌缺血缺氧或坏死的心脏病，又称缺血性心脏病。\n\n冠心病是全球范围内导致死亡的首要原因，我国冠心病患病人数约1100万，每年因冠心病死亡人数超过100万。\n\n### 危险因素\n\n**不可改变的危险因素：**\n- 年龄：男性≥45岁，女性≥55岁\n- 性别：男性发病率高于绝经前女性\n- 家族史：一级亲属中男性<55岁或女性<65岁患冠心病\n\n**可改变的危险因素：**\n- 高血压\n- 血脂异常（高LDL-C、低HDL-C、高TG）\n- 糖尿病\n- 吸烟\n- 肥胖（BMI≥28 kg/m²）\n- 缺乏体力活动\n- 精神心理因素（抑郁、焦虑、A型性格）\n\n## 二、临床分型\n\n### 2.1 慢性冠脉综合征（CCS）\n- **稳定型心绞痛**：劳力时出现胸痛，休息或含服硝酸甘油后缓解\n- **缺血性心肌病**：心肌长期慢性缺血导致心功能不全\n- **隐匿型冠心病**：有心肌缺血客观证据但无症状','file_14_chunk_0','2026-08-12 15:33:37'),
(13,14,1,'### 2.2 急性冠脉综合征（ACS）\n- **不稳定型心绞痛（UA）**：新发心绞痛、心绞痛加重或静息时发作\n- **非ST段抬高型心肌梗死（NSTEMI）**\n- **ST段抬高型心肌梗死（STEMI）**\n\n## 三、临床症状\n\n### 3.1 典型心绞痛特征\n1. **部位**：胸骨后或心前区，范围约拳头大小\n2. **性质**：压迫感、紧缩感、烧灼感或窒息感（非针刺样或刀割样）\n3. **持续时间**：典型发作3-5分钟，一般不超过15-20分钟\n4. **诱因**：体力活动、情绪激动、饱餐、寒冷刺激\n5. **缓解方式**：休息或含服硝酸甘油1-3分钟内缓解\n6. **放射部位**：左肩、左臂内侧、颈部、下颌、上腹部\n\n### 3.2 不典型症状\n- 上腹部疼痛（尤其下壁心肌缺血）\n- 牙痛、咽部紧缩感\n- 仅表现为呼吸困难\n- 异常疲劳感\n- 老年患者可无痛性心肌缺血\n\n### 3.3 心肌梗死症状\n- 持续剧烈胸痛（>30分钟），硝酸甘油不能缓解\n- 大汗淋漓、面色苍白\n- 恶心呕吐\n- 呼吸困难\n- 濒死感\n- 心律失常、血压下降\n\n## 四、诊断方法','file_14_chunk_1','2026-08-12 15:33:37'),
(14,14,2,'## 四、诊断方法\n\n### 4.1 无创检查\n| 检查方法 | 适用场景 | 敏感度/特异度 |\n|---------|---------|-------------|\n| 静息心电图 | 初步筛查 | 敏感度低（约50%）|\n| 运动平板心电图 | 可疑稳定型心绞痛 | 敏感度68%，特异度77% |\n| 冠脉CT血管造影（CTA） | 中低危患者排除冠心病 | 敏感度95%，特异度83% |\n| 心脏超声 | 评估心功能、室壁运动 | — |\n| 负荷超声心动图 | 不能运动的患者 | 敏感度80-85% |\n| 心肌核素显像（SPECT） | 评估心肌缺血范围 | 敏感度87%，特异度73% |\n\n### 4.2 有创检查\n- **冠状动脉造影（CAG）**：诊断金标准，可直观显示冠脉狭窄程度和部位\n- **血管内超声（IVUS）**：评估斑块性质和管腔面积\n- **光学相干断层扫描（OCT）**：高分辨率评估斑块和支架贴壁情况\n- **冠脉血流储备分数（FFR）**：功能学评估狭窄是否引起心肌缺血\n\n## 五、治疗方案','file_14_chunk_2','2026-08-12 15:33:37'),
(15,14,3,'## 五、治疗方案\n\n### 5.1 药物治疗（ABCDE方案）\n- **A**：Antiplatelet（抗血小板）+ ACEI/ARB\n  - 阿司匹林75-100mg/日（终身）\n  - ACS后加用P2Y12抑制剂12个月\n  - ACEI/ARB用于合并高血压、心衰、糖尿病者\n\n- **B**：Beta-blocker（β受体阻滞剂）+ Blood pressure control\n  - 美托洛尔、比索洛尔\n  - 目标心率55-60次/分\n\n- **C**：Cholesterol lowering（调脂）+ Cigarette quitting（戒烟）\n  - 他汀类药物：阿托伐他汀、瑞舒伐他汀\n  - LDL-C目标：<1.8 mmol/L（高危）或<1.4 mmol/L（极高危）\n\n- **D**：Diabetes management（糖尿病管理）+ Diet（饮食）\n  - HbA1c目标<7.0%\n  - 地中海饮食模式\n\n- **E**：Exercise（运动）+ Education（健康教育）\n  - 每周≥150分钟中等强度有氧运动','file_14_chunk_3','2026-08-12 15:33:37'),
(16,14,4,'- **E**：Exercise（运动）+ Education（健康教育）\n  - 每周≥150分钟中等强度有氧运动\n\n### 5.2 血运重建治疗\n#### 经皮冠状动脉介入治疗（PCI）\n- 适应证：STEMI首选、药物治疗无效的稳定型心绞痛、高危ACS\n- 药物洗脱支架（DES）为标准治疗\n- 术后需双联抗血小板治疗（DAPT）至少6-12个月\n\n#### 冠状动脉旁路移植术（CABG）\n- 适应证：左主干病变、三支病变合并糖尿病或左室功能低下\n- 动脉桥（左侧内乳动脉）优于静脉桥\n- 10年通畅率：内乳动脉桥>90%，大隐静脉桥约60%\n\n## 六、预后与随访\n\n- 规范药物治疗可显著改善预后\n- PCI术后1个月、3个月、6个月、12个月随访\n- 每年进行心血管风险因素评估\n- 终身坚持二级预防药物治疗\n- 心脏康复可改善运动耐量和生活质量\n\n## 参考文献','file_14_chunk_4','2026-08-12 15:33:37'),
(17,14,5,'## 参考文献\n\n1. 中华医学会心血管病学分会. 稳定性冠心病诊断与治疗指南（2023）\n2. 2023 ESC Guidelines for the management of acute coronary syndromes\n3. Fihn SD, et al. 2014 ACC/AHA Guideline for Stable Ischemic Heart Disease','file_14_chunk_5','2026-08-12 15:33:37'),
(18,15,0,'甲状腺功能亢进症（甲亢）诊疗手册\n一、疾病概述\n甲状腺功能亢进症（Hyperthyroidism），简称甲亢，是由于甲状腺合成和分泌过多的甲状腺激素（\nT3、T4），导致机体代谢亢进和交感神经兴奋性增高，引起心悸、出汗、进食增多伴体重下降、突\n眼等一组临床综合征。\n最常见的病因是Graves病（毒性弥漫性甲状腺肿），占所有甲亢的80-85%。Graves病是一种器官特\n异性自身免疫病，甲状腺刺激性抗体（TSAb/TRAb）与TSH受体结合，持续刺激甲状腺合成和释放过\n量甲状腺激素。\n流行病学：甲亢在人群中的患病率约为1.3%，女性是男性的5-10倍。好发年龄20-50岁。\n二、病因分类\n1. Graves病（最常见，约80-85%）\n2. 毒性多结节性甲状腺肿（约10-15%）\n3. 毒性甲状腺腺瘤（Plummer病）\n4. 亚急性甲状腺炎（一过性甲亢）\n5. 碘致甲亢（碘甲亢）\n6. 药物性甲亢（如胺碘酮）\n7. TSH分泌性垂体瘤（罕见）\n8. 妊娠一过性甲亢（hCG介导）\n三、临床表现\n（一）高代谢综合征：\n- 怕热、多汗、皮肤温暖潮湿\n- 体重下降（尽管食欲亢进、进食增多）','file_15_chunk_0','2026-08-12 15:34:10'),
(19,15,1,'8. 妊娠一过性甲亢（hCG介导）\n三、临床表现\n（一）高代谢综合征：\n- 怕热、多汗、皮肤温暖潮湿\n- 体重下降（尽管食欲亢进、进食增多）\n- 疲乏无力\n- 低热\n（二）精神神经系统：\n- 紧张、焦虑、易激动、烦躁失眠\n- 双手细颤（伸手平举时明显）','file_15_chunk_1','2026-08-12 15:34:10'),
(20,15,2,'- 腱反射活跃\n（三）心血管系统：\n- 心悸、心动过速（静息心率>90次/分）\n- 脉压差增大（收缩压升高、舒张压降低）\n- 心房颤动（约10-15%，老年人更常见）\n- 重症可发生心力衰竭（甲亢性心脏病）\n（四）消化系统：\n- 食欲亢进、大便次数增多\n- 肝功能异常\n（五）肌肉骨骼系统：\n- 近端肌无力（蹲起困难）\n- 骨质疏松\n- 周期性低钾性麻痹（亚洲男性多见）\n（六）生殖系统：\n- 女性月经减少或闭经\n- 男性勃起功能障碍、乳房发育\n（七）Graves病特有表现：\n- 弥漫性甲状腺肿大（双侧对称，质软有弹性，可触及震颤/闻及血管杂音）\n- Graves眼病：突眼、眼睑退缩、上睑迟落（von Graefe征）、眼球运动受限、复视\n- 胫前黏液性水肿（少见，约1-4%）\n- 甲状腺肢端肥大症（罕见）\n四、诊断\n4.1 实验室检查：\n- 血清TSH降低（<0.1 mIU/L）：最敏感的筛查指标\n- 血清FT4升高：确诊甲亢\n- 血清FT3升高：部分患者仅FT3升高（T3型甲亢）\n- TRAb（TSH受体抗体）：Graves病阳性率>95%\n- TPOAb、TgAb：可阳性','file_15_chunk_2','2026-08-12 15:34:10'),
(21,15,3,'- 血清FT3升高：部分患者仅FT3升高（T3型甲亢）\n- TRAb（TSH受体抗体）：Graves病阳性率>95%\n- TPOAb、TgAb：可阳性\n4.2 影像学检查：','file_15_chunk_3','2026-08-12 15:34:10'),
(22,15,4,'- 甲状腺超声：评估甲状腺大小、结节、血流情况\n- 甲状腺核素显像（\0\0\0I或\0\0\0Tc）：\n* Graves病：弥漫性摄取增高\n* 毒性腺瘤：热结节，周围组织受抑制\n* 亚急性甲状腺炎：摄取降低\n- 甲状腺摄碘率（RAIU）：Graves病增高，甲状腺炎降低\n4.3 诊断流程：\n1. 临床表现疑似甲亢 → 检测TSH\n2. TSH降低 → 检测FT4、FT3\n3. FT4/FT3升高 → 确诊甲亢\n4. 检测TRAb → 鉴别Graves病\n5. 必要时行甲状腺核素显像 → 明确病因\n五、治疗方案\n5.1 抗甲状腺药物治疗（ATD）\n适用于：Graves病首选、轻中度甲亢、年轻患者、妊娠期\n常用药物：\n（1）甲巯咪唑（MMI/他巴唑）：首选药物\n- 起始剂量：10-30mg/日（根据病情严重程度）\n- 维持剂量：5-10mg/日\n- 疗程：12-18个月\n（2）丙硫氧嘧啶（PTU）：\n- 适用于妊娠早期、甲状腺危象\n- 起始剂量：200-400mg/日，分3次\n- 维持剂量：50-100mg/日\n不良反应监测：','file_15_chunk_4','2026-08-12 15:34:10'),
(23,15,5,'（2）丙硫氧嘧啶（PTU）：\n- 适用于妊娠早期、甲状腺危象\n- 起始剂量：200-400mg/日，分3次\n- 维持剂量：50-100mg/日\n不良反应监测：\n- 粒细胞缺乏症（发生率0.2-0.5%）：最严重的不良反应，表现为高热、咽痛。用药前和用药期间\n定期检测血常规\n- 肝功能损害：PTU可致严重肝损害，MMI多为胆汁淤积型\n- 皮疹、关节痛、血管炎（PTU）\n5.2 放射性碘（\0\0\0I）治疗','file_15_chunk_5','2026-08-12 15:34:10'),
(24,15,6,'适用于：ATD治疗失败或复发、药物不良反应、甲状腺肿大明显\n禁忌：妊娠、哺乳期、重度活动性Graves眼病\n剂量：根据甲状腺大小和摄碘率计算，通常5-15 mCi\n注意：治疗后大多数患者最终发展为甲减，需终身甲状腺激素替代治疗\n5.3 手术治疗\n适用于：甲状腺显著肿大、压迫症状、怀疑合并甲状腺癌、药物治疗无效\n术式：甲状腺全切除术或近全切除术\n术前准备：ATD控制甲功正常 + 碘剂（Lugol液）10-14天减少血供\n并发症：甲减（最常见）、喉返神经损伤、甲状旁腺功能减退\n5.4 辅助治疗\n- β受体阻滞剂（普萘洛尔20-40mg，每日3-4次）：控制心动过速、震颤等交感神经兴奋症状\n- Graves眼病治疗：轻度使用人工泪液、太阳镜；中重度使用糖皮质激素、眼眶放疗或手术\n六、特殊情况处理\n1. 甲状腺危象：\n- 诱因：感染、手术、创伤、放射性碘治疗后\n- 表现：高热（>39°C）、心动过速（>140次/分）、大汗、烦躁谵妄、恶心呕吐腹泻\n- 治疗：PTU 600mg负荷量后200mg每4小时；碘剂（PTU后1小时给予）；普萘洛尔；糖皮质激素（氢','file_15_chunk_6','2026-08-12 15:34:10'),
(25,15,7,'- 治疗：PTU 600mg负荷量后200mg每4小时；碘剂（PTU后1小时给予）；普萘洛尔；糖皮质激素（氢\n化可的松100mg每8小时）；物理降温；支持治疗\n2. 妊娠合并甲亢：\n- 妊娠早期首选PTU，妊娠中晚期可换用MMI\n- 控制FT4在正常上限或略高于正常上限\n- 使用最小有效剂量的ATD\n- 禁用放射性碘治疗\n- 每2-4周复查甲功','file_15_chunk_7','2026-08-12 15:34:10'),
(26,16,0,'慢性肾脏病（CKD）症状识别与诊疗方案\n\n一、疾病定义\n\n慢性肾脏病（Chronic Kidney Disease, CKD）是指各种原因引起的肾脏结构或功能异常持续≥3个月。诊断标准为以下任一条持续超过3个月：\n\n1. 肾损伤标志：\n   - 白蛋白尿（UACR≥30 mg/g）\n   - 尿沉渣异常（血尿、管型尿）\n   - 肾小管相关异常\n   - 影像学检查发现结构异常\n   - 肾移植病史\n   - 肾活检病理异常\n\n2. 肾小球滤过率（GFR）下降：eGFR<60 ml/min/1.73m²\n\n流行病学：\n全球CKD患病率约为9.1%（约7亿人），我国成人CKD患病率约10.8%，患者约1.2亿人。CKD已成为重要的公共卫生问题，是全球第12位死因，且患病率持续上升。\n\n二、病因','file_16_chunk_0','2026-08-12 15:34:19'),
(27,16,1,'二、病因\n\n1. 糖尿病肾病：全球最常见病因（约30-50%），我国已超过肾小球肾炎成为首位病因\n2. 高血压肾损害：长期高血压导致的肾小动脉硬化\n3. 慢性肾小球肾炎：包括IgA肾病、膜性肾病、局灶节段性肾小球硬化\n4. 多囊肾病：常染色体显性遗传性多囊肾病（ADPKD）\n5. 梗阻性肾病：前列腺增生、肾结石等引起的尿路梗阻\n6. 间质性肾炎：药物性（NSAIDs、中草药）、感染性\n7. 狼疮性肾炎：系统性红斑狼疮累及肾脏\n8. 其他：痛风性肾病、淀粉样变性等\n\n三、分期\n\nCKD分期（基于eGFR）：\n\nG1期：eGFR≥90 ml/min/1.73m²，肾功能正常或增高，但有肾损伤证据\nG2期：eGFR 60-89 ml/min/1.73m²，肾功能轻度下降\nG3a期：eGFR 45-59 ml/min/1.73m²，肾功能轻中度下降\nG3b期：eGFR 30-44 ml/min/1.73m²，肾功能中重度下降\nG4期：eGFR 15-29 ml/min/1.73m²，肾功能重度下降\nG5期：eGFR<15 ml/min/1.73m²，肾衰竭（终末期肾病，ESRD）','file_16_chunk_1','2026-08-12 15:34:19'),
(28,16,2,'白蛋白尿分期：\nA1：UACR<30 mg/g（正常至轻度升高）\nA2：UACR 30-300 mg/g（中度升高，微量白蛋白尿）\nA3：UACR>300 mg/g（重度升高，大量白蛋白尿）\n\n四、临床症状\n\nCKD早期通常无明显症状，随着肾功能下降逐渐出现以下表现：\n\n（一）泌尿系统症状\n- 夜尿增多：常为最早出现的症状，因肾小管浓缩功能下降\n- 尿量改变：早期多尿，晚期少尿\n- 尿液异常：蛋白尿（泡沫尿）、血尿\n- 水肿：眼睑和下肢水肿，严重者全身水肿\n\n（二）心血管系统\n- 高血压：约80-85%的CKD患者伴有高血压\n- 心力衰竭：容量超负荷、贫血、尿毒症毒素导致\n- 心包炎：尿毒症性心包炎\n- 动脉粥样硬化加速：CKD患者心血管疾病风险显著升高\n\n（三）血液系统\n- 肾性贫血：促红细胞生成素（EPO）分泌减少，通常eGFR<45时出现\n- 出血倾向：血小板功能异常\n\n（四）骨骼系统（CKD-MBD）\n- 肾性骨病：骨痛、骨折\n- 继发性甲状旁腺功能亢进\n- 血管和软组织钙化\n- 高磷血症、低钙血症','file_16_chunk_2','2026-08-12 15:34:19'),
(29,16,3,'（四）骨骼系统（CKD-MBD）\n- 肾性骨病：骨痛、骨折\n- 继发性甲状旁腺功能亢进\n- 血管和软组织钙化\n- 高磷血症、低钙血症\n\n（五）消化系统\n- 食欲减退、恶心呕吐（尿毒症毒素刺激）\n- 口中尿臭味\n- 消化道出血\n\n（六）神经系统\n- 尿毒症性脑病：嗜睡、注意力不集中、意识障碍\n- 周围神经病变：感觉异常、不宁腿综合征\n- 肌阵挛、扑翼样震颤\n\n（七）皮肤症状\n- 皮肤瘙痒：磷蓄积和甲旁亢导致\n- 皮肤色素沉着：皮肤呈暗黄色或灰褐色\n- 尿毒症霜：皮肤表面尿素结晶\n\n（八）免疫功能\n- 免疫力下降，易感染\n- 疫苗接种反应减弱\n\n五、诊断','file_16_chunk_3','2026-08-12 15:34:19'),
(30,16,4,'（八）免疫功能\n- 免疫力下降，易感染\n- 疫苗接种反应减弱\n\n五、诊断\n\n5.1 实验室检查\n1. 血肌酐和eGFR：\n   - eGFR计算公式：CKD-EPI方程\n   - 胱抑素C可辅助评估肾功能\n2. 尿液检查：\n   - 尿常规：蛋白、红细胞、管型\n   - UACR（尿白蛋白/肌酐比值）\n   - 24小时尿蛋白定量\n3. 血液生化：\n   - 电解质（钾、钙、磷）\n   - 尿酸、尿素氮\n   - 血红蛋白\n   - 白蛋白\n   - 甲状旁腺激素（iPTH）\n   - 25-羟维生素D\n4. 免疫学检查（必要时）：\n   - 抗核抗体、抗dsDNA抗体（排除狼疮性肾炎）\n   - ANCA（排除血管炎）\n   - 补体C3、C4\n   - 免疫球蛋白和轻链\n\n5.2 影像学检查\n- 肾脏超声：评估肾脏大小、皮质厚度、有无梗阻和囊肿\n- CT/MRI：进一步评估肾脏形态和血管\n- 肾动脉超声/CTA：排除肾动脉狭窄','file_16_chunk_4','2026-08-12 15:34:19'),
(31,16,5,'5.2 影像学检查\n- 肾脏超声：评估肾脏大小、皮质厚度、有无梗阻和囊肿\n- CT/MRI：进一步评估肾脏形态和血管\n- 肾动脉超声/CTA：排除肾动脉狭窄\n\n5.3 肾活检\n适应证：原因不明的蛋白尿或血尿、肾病综合征、怀疑系统性疾病累及肾脏、急性肾损伤原因不明\n禁忌证：孤立肾、出血倾向、小肾脏、严重高血压未控制\n\n六、治疗\n\n6.1 延缓CKD进展的核心措施\n\n（1）控制血压\n- 目标：合并蛋白尿者<130/80 mmHg\n- 首选药物：ACEI或ARB（肾脏保护作用）\n  * 依那普利、贝那普利（ACEI）\n  * 缬沙坦、厄贝沙坦（ARB）\n- 注意：双侧肾动脉狭窄禁用，高钾血症者慎用\n- 需监测血钾和肌酐（用药2周和4周后复查）\n\n（2）控制蛋白尿\n- ACEI/ARB：减少蛋白尿30-50%\n- SGLT2抑制剂（达格列净、恩格列净）：无论是否合并糖尿病均获益\n  * DAPA-CKD研究和EMPA-KIDNEY研究证实延缓CKD进展\n- 非奈利酮（Finerenone）：新型非甾体MRA，适用于糖尿病肾病','file_16_chunk_5','2026-08-12 15:34:19'),
(32,16,6,'（3）控制血糖（糖尿病肾病）\n- HbA1c目标<7.0%（个体化调整）\n- 优先选择有肾脏获益的降糖药：SGLT2抑制剂、GLP-1受体激动剂\n- 二甲双胍：eGFR<30时禁用\n- 避免使用格列本脲等经肾排泄的磺脲类\n\n（4）饮食管理\n- 低蛋白饮食：CKD 3-5期，蛋白摄入0.6-0.8 g/kg/日\n- 限制钠盐：<5 g/日\n- 限制钾摄入：高钾血症时限制含钾高的食物\n- 限制磷摄入：避免高磷食品（加工食品、碳酸饮料）\n- 充足热量：30-35 kcal/kg/日\n\n6.2 并发症管理\n\n（1）贫血管理\n- 检测指标：血红蛋白、铁蛋白、转铁蛋白饱和度\n- 铁剂补充：铁蛋白<100 ng/mL或TSAT<20%时\n- EPO/ESA治疗：Hb<100 g/L时考虑，目标Hb 100-120 g/L\n- 罗沙司他（HIF-PHI）：新型口服药物\n\n（2）矿物质和骨代谢异常（CKD-MBD）\n- 控制高磷血症：限磷饮食 + 磷结合剂（碳酸钙、醋酸钙、碳酸镧、司维拉姆）\n- 补充维生素D：骨化三醇或阿法骨化醇\n- 甲旁亢管理：西那卡塞（拟钙剂）','file_16_chunk_6','2026-08-12 15:34:19'),
(33,16,7,'（3）代谢性酸中毒\n- 血清碳酸氢盐<22 mmol/L时补充碳酸氢钠\n\n（4）高钾血症\n- 限制含钾食物\n- 排钾利尿剂\n- 口服钾结合剂（环硅酸锆钠、Patiromer）\n\n6.3 肾脏替代治疗（eGFR<10-15或有明显尿毒症症状时）\n\n（1）血液透析\n- 每周3次，每次4小时\n- 需建立血管通路（动静脉内瘘或中心静脉导管）\n\n（2）腹膜透析\n- 适合居家治疗、残余肾功能保存较好的患者\n- 持续不卧床腹膜透析（CAPD）每日4-5次换液\n\n（3）肾移植\n- 最佳肾替代治疗方式\n- 活体肾移植优于尸体肾移植\n- 需终身服用免疫抑制剂\n\n七、随访监测\n\nCKD G1-G2期：每年监测1-2次\nCKD G3期：每3-6个月监测\nCKD G4期：每1-3个月监测\nCKD G5期：每1个月监测\n\n监测项目：\n- 血肌酐、eGFR\n- UACR或24h尿蛋白\n- 血常规（Hb）\n- 电解质（K⁺、Ca²⁺、P³⁻）\n- iPTH（G3b期以后）\n- 血脂\n- 血糖/HbA1c（糖尿病患者）','file_16_chunk_7','2026-08-12 15:34:19'),
(34,16,8,'参考文献：\n1. KDIGO 2024 Clinical Practice Guideline for the Evaluation and Management of CKD\n2. 中国慢性肾脏病早期评价与管理指南（2023版）\n3. Heerspink HJL, et al. Dapagliflozin in Patients with CKD. N Engl J Med. 2020\n4. The EMPA-KIDNEY Collaborative Group. Empagliflozin in Patients with CKD. N Engl J Med. 2023','file_16_chunk_8','2026-08-12 15:34:19'),
(35,17,0,'2型糖尿病综合管理临床指南\n一、概述\n2型糖尿病（T2DM）是一种以胰岛素抵抗和胰岛β细胞功能进行性减退为特征的代谢性疾病。我国是全球糖尿病患者最多的国家，成人糖尿病患病率已达12.8%，患者人数超过1.4亿。2型糖尿病如不加以控制，可引起心脑血管疾病、视网膜病变、糖尿病肾病、糖尿病足等严重并发症。\n二、诊断标准\n（1）空腹血糖（FPG）≥7.0 mmol/L（空腹定义为至少8小时未摄入热量）\n（2）口服糖耐量试验（OGTT）2小时血糖≥11.1 mmol/L\n（3）糖化血红蛋白（HbA1c）≥6.5%\n（4）随机血糖≥11.1 mmol/L且伴有典型糖尿病症状（多饮、多食、多尿、体重下降）\n糖尿病前期诊断标准：\n- 空腹血糖受损（IFG）：FPG 6.1-6.9 mmol/L，OGTT 2h血糖<7.8 mmol/L\n- 糖耐量减低（IGT）：FPG<7.0 mmol/L，OGTT 2h血糖7.8-11.0 mmol/L\n三、综合治疗目标\n1. 血糖控制目标：\n   - HbA1c<7.0%（一般成人）\n   - HbA1c<6.5%（年轻、病程短、无并发症者）','file_17_chunk_0','2026-08-12 15:37:50'),
(36,17,1,'三、综合治疗目标\n1. 血糖控制目标：\n   - HbA1c<7.0%（一般成人）\n   - HbA1c<6.5%（年轻、病程短、无并发症者）\n   - HbA1c<8.0%（老年、预期寿命有限、低血糖风险高者）\n   - 空腹血糖：4.4-7.0 mmol/L\n   - 餐后2小时血糖：<10.0 mmol/L\n2. 血压控制：<130/80 mmHg\n3. 血脂控制：\n   - LDL-C<2.6 mmol/L（无心血管疾病者）\n   - LDL-C<1.8 mmol/L（合并心血管疾病者）\n   - TG<1.7 mmol/L\n4. 体重管理：BMI<24 kg/m²\n四、药物治疗方案\n第一阶段：生活方式干预 + 二甲双胍\n二甲双胍是2型糖尿病一线用药，起始剂量500mg，每日1-2次，可逐渐增至最大剂量2000mg/日。主要不良反应为胃肠道反应，肾功能不全（eGFR<30 ml/min/1.73m²）禁用。\n第二阶段：二甲双胍 + 第二种降糖药物\n可选药物包括：\n- SGLT2抑制剂（恩格列净、达格列净）：具有心血管和肾脏获益','file_17_chunk_1','2026-08-12 15:37:50'),
(37,17,2,'第二阶段：二甲双胍 + 第二种降糖药物\n可选药物包括：\n- SGLT2抑制剂（恩格列净、达格列净）：具有心血管和肾脏获益\n- GLP-1受体激动剂（利拉鲁肽、司美格鲁肽）：减重效果显著\n- DPP-4抑制剂（西格列汀、利格列汀）：低血糖风险低\n- 磺脲类（格列美脲、格列齐特）：降糖效果确切，价格低廉\n- α-糖苷酶抑制剂（阿卡波糖）：主要降低餐后血糖\n- 噻唑烷二酮类（吡格列酮）：改善胰岛素抵抗\n第三阶段：三药联合或起始胰岛素治疗\n当HbA1c>9.0%或FPG>11.1 mmol/L时，可直接起始胰岛素治疗。\n五、并发症监测与管理\n1. 眼底检查：确诊后即刻筛查，之后每年1次\n2. 肾功能检查：每年检测尿微量白蛋白/肌酐比值（UACR）和eGFR\n3. 足部检查：每次就诊时检查，每年进行全面足部评估\n4. 神经病变筛查：确诊5年后每年筛查\n5. 心血管风险评估：每年评估，包括血压、血脂、心电图等\n6. 口腔检查：每6个月进行一次口腔检查\n六、生活方式管理\n1. 医学营养治疗（MNT）：\n   - 碳水化合物占总热量45-60%\n   - 脂肪占总热量25-35%','file_17_chunk_2','2026-08-12 15:37:50'),
(38,17,3,'六、生活方式管理\n1. 医学营养治疗（MNT）：\n   - 碳水化合物占总热量45-60%\n   - 脂肪占总热量25-35%\n   - 蛋白质占总热量15-20%\n   - 膳食纤维每日25-30g\n   - 限制添加糖摄入\n2. 运动治疗：\n   - 每周至少150分钟中等强度有氧运动\n   - 每周2-3次抗阻运动\n   - 避免连续2天以上不运动\n   - 运动前后监测血糖，防止低血糖\n3. 自我血糖监测（SMBG）：\n   - 使用胰岛素者：每日监测3-4次\n   - 口服药物者：每周监测2-4次','file_17_chunk_3','2026-08-12 15:37:50'),
(39,18,0,'# 高血压临床诊疗指南\n\n## 一、概述\n\n高血压是以体循环动脉血压持续升高为主要特征的慢性疾病，是心脑血管疾病最重要的危险因素。我国高血压患病率逐年上升，目前约有2.45亿高血压患者。\n\n## 二、诊断标准\n\n### 2.1 血压分级\n\n| 分级 | 收缩压(mmHg) | 舒张压(mmHg) |\n|------|-------------|-------------|\n| 正常血压 | <120 | <80 |\n| 正常高值 | 120-139 | 80-89 |\n| 1级高血压（轻度） | 140-159 | 90-99 |\n| 2级高血压（中度） | 160-179 | 100-109 |\n| 3级高血压（重度） | ≥180 | ≥110 |\n\n### 2.2 诊断要点\n\n1. 非同日3次诊室血压测量，收缩压≥140mmHg和/或舒张压≥90mmHg\n2. 24小时动态血压监测（ABPM）：24h平均血压≥130/80mmHg\n3. 家庭自测血压：≥135/85mmHg\n\n## 三、治疗原则\n\n### 3.1 非药物治疗','file_18_chunk_0','2026-08-12 15:37:56'),
(40,18,1,'## 三、治疗原则\n\n### 3.1 非药物治疗\n\n- **饮食调整**：减少钠盐摄入（每日<6g），增加钾摄入\n- **控制体重**：BMI控制在18.5-23.9 kg/m²\n- **规律运动**：每周≥5天，每次30分钟的中等强度有氧运动\n- **限制饮酒**：男性每日酒精量<25g，女性<15g\n- **戒烟**：完全戒烟，避免被动吸烟\n- **心理平衡**：减轻精神压力，保持心态平和\n\n### 3.2 药物治疗\n\n#### 一线降压药物\n\n1. **钙通道阻滞剂（CCB）**：氨氯地平、硝苯地平控释片\n2. **血管紧张素转换酶抑制剂（ACEI）**：依那普利、贝那普利\n3. **血管紧张素II受体拮抗剂（ARB）**：缬沙坦、厄贝沙坦\n4. **利尿剂**：氢氯噻嗪、吲达帕胺\n5. **β受体阻滞剂**：美托洛尔、比索洛尔\n\n#### 联合用药方案\n\n- ACEI/ARB + CCB\n- ACEI/ARB + 利尿剂\n- CCB + 利尿剂\n- CCB + β受体阻滞剂\n\n## 四、目标血压','file_18_chunk_1','2026-08-12 15:37:56'),
(41,18,2,'- ACEI/ARB + CCB\n- ACEI/ARB + 利尿剂\n- CCB + 利尿剂\n- CCB + β受体阻滞剂\n\n## 四、目标血压\n\n- 一般高血压患者：<140/90mmHg\n- 65-79岁老年人：<150/90mmHg，如耐受可降至<140/90mmHg\n- ≥80岁老年人：<150/90mmHg\n- 合并糖尿病、慢性肾病：<130/80mmHg\n\n## 五、随访管理\n\n- 血压达标且稳定者：每1-3个月随访一次\n- 血压未达标或不稳定者：每2-4周随访一次\n- 每年至少进行一次全面评估，包括靶器官损害和心血管危险因素\n\n## 六、参考文献\n\n1. 中国高血压防治指南修订委员会. 中国高血压防治指南（2024年修订版）\n2. Williams B, et al. 2018 ESC/ESH Guidelines for the management of arterial hypertension\n3. Whelton PK, et al. 2017 ACC/AHA Guideline for High Blood Pressure in Adults','file_18_chunk_2','2026-08-12 15:37:56'),
(42,19,0,'急性心肌梗死诊疗指南\n一、定义与分型\n急性心肌梗死（AMI）是指在冠状动脉病变的基础上，发生冠状动脉血供急剧减少或中断，使相应心\n肌严重而持久地急性缺血导致心肌坏死。根据心电图表现分为：\n1. ST段抬高型心肌梗死（STEMI）：急性心肌缺血导致的胸痛，伴有持续性ST段抬高或新出现的左\n束支传导阻滞，以及心肌坏死生物标志物升高。\n2. 非ST段抬高型心肌梗死（NSTEMI）：有急性心肌缺血的临床表现和心肌坏死标志物升高，但心电\n图无持续性ST段抬高。\n二、临床表现\n1. 典型症状：\n- 胸骨后或心前区剧烈压榨性疼痛，持续时间≥30分钟\n- 疼痛可放射至左肩、左臂内侧、颈部、下颌或背部\n- 常伴有大汗淋漓、恶心呕吐、呼吸困难\n- 有濒死感和恐惧感\n- 含服硝酸甘油不能完全缓解\n2. 不典型症状：\n- 老年患者可表现为突发呼吸困难、意识障碍\n- 糖尿病患者可无明显胸痛（无痛性心梗）\n- 部分患者以上腹痛、牙痛、咽部紧缩感为首发症状\n三、诊断\n诊断标准（满足以下三项中至少两项）：\n1. 典型缺血性胸痛症状\n2. 心电图动态演变：\n- STEMI：相邻两个或以上导联新出现ST段抬高','file_19_chunk_0','2026-08-12 15:38:02'),
(43,19,1,'三、诊断\n诊断标准（满足以下三项中至少两项）：\n1. 典型缺血性胸痛症状\n2. 心电图动态演变：\n- STEMI：相邻两个或以上导联新出现ST段抬高\n- NSTEMI：ST段压低、T波倒置或一过性ST段抬高\n3. 心肌坏死标志物升高：\n- 高敏肌钙蛋白I或T（hs-cTn）升高超过参考值上限第99百分位','file_19_chunk_1','2026-08-12 15:38:02'),
(44,19,2,'- 肌酸激酶同工酶（CK-MB）升高\n四、急诊处理流程\n1. 院前急救：\n- 立即拨打120急救电话\n- 让患者平卧休息，避免活动\n- 嚼服阿司匹林300mg（无禁忌证时）\n- 舌下含服硝酸甘油0.5mg（收缩压>90mmHg时）\n- 持续心电监护\n2. 再灌注治疗策略：\nSTEMI患者再灌注治疗时间窗：\n- 发病12小时内，首选直接经皮冠状动脉介入治疗（PCI）\n- Door-to-Balloon时间目标：≤90分钟\n- 无法在120分钟内完成PCI时，可考虑溶栓治疗\n- 溶栓药物：阿替普酶、瑞替普酶或尿激酶\n- Door-to-Needle时间目标：≤30分钟\n3. 抗栓治疗：\n- 双联抗血小板治疗（DAPT）：阿司匹林 + P2Y12受体拮抗剂（替格瑞洛或氯吡格雷）\n- 抗凝治疗：低分子肝素或普通肝素\n- DAPT疗程：PCI术后至少12个月\n五、住院期间管理\n1. 监护：入院后持续心电监护至少48小时\n2. 卧床休息：无并发症者12小时后可床上活动\n3. 吸氧：血氧饱和度<90%时给予吸氧\n4. 镇痛：吗啡3-5mg静脉注射（无禁忌证时）','file_19_chunk_2','2026-08-12 15:38:02'),
(45,19,3,'2. 卧床休息：无并发症者12小时后可床上活动\n3. 吸氧：血氧饱和度<90%时给予吸氧\n4. 镇痛：吗啡3-5mg静脉注射（无禁忌证时）\n5. 药物治疗：β受体阻滞剂、ACEI/ARB、他汀类药物\n6. 评估左室功能：超声心动图评估LVEF\n六、出院后管理','file_19_chunk_3','2026-08-12 15:38:02'),
(46,19,4,'1. 长期药物治疗：阿司匹林（终身）、P2Y12受体拮抗剂（12个月）、他汀类（终身）、β受体阻\n滞剂、ACEI/ARB\n2. 心脏康复：出院后2-6周开始，每周3-5次运动训练\n3. 危险因素控制：戒烟、控制血压血脂血糖、健康饮食、规律运动\n4. 定期随访：出院后1个月、3个月、6个月、12个月及此后每年','file_19_chunk_4','2026-08-12 15:38:02'),
(47,20,0,'慢性阻塞性肺疾病（COPD）诊疗指南\n\n一、定义\n\n慢性阻塞性肺疾病（COPD）是一种常见的、可预防和可治疗的慢性气道疾病，以持续存在的呼吸道症状和气流受限为特征。气流受限呈进行性发展，与气道和（或）肺泡对有毒颗粒或气体的异常炎症反应有关。\n\n全球约有3.84亿COPD患者，我国40岁以上人群COPD患病率为13.7%，患者近1亿人，已成为我国第三大死因。\n\n二、危险因素\n\n1. 吸烟：最重要的危险因素，约80-90%的COPD患者有吸烟史\n2. 职业粉尘和化学物质暴露：如二氧化硅、煤尘、棉尘等\n3. 室内外空气污染：生物燃料烟雾、PM2.5等\n4. 遗传因素：α1-抗胰蛋白酶缺乏症\n5. 幼年时期的呼吸道感染和肺发育不良\n6. 哮喘和气道高反应性\n\n三、临床表现','file_20_chunk_0','2026-08-12 15:38:08'),
(48,20,1,'三、临床表现\n\n主要症状：\n1. 慢性咳嗽：通常为首发症状，初起为间歇性咳嗽，晨起明显，以后逐渐发展为终日咳嗽\n2. 咳痰：一般为白色黏液或浆液性泡沫痰，急性加重时痰量增多，可为脓性痰\n3. 呼吸困难或气短：标志性症状，早期仅于活动后出现，后逐渐加重，以致日常活动甚至休息时也感气短\n4. 喘息和胸闷：部分患者特别是重度患者可出现\n5. 全身症状：体重下降、肌肉萎缩、食欲减退、焦虑抑郁等\n\n四、诊断\n\n4.1 肺功能检查（确诊的金标准）\n- 支气管舒张剂后FEV1/FVC<0.70，确认存在持续性气流受限\n- 肺功能分级（GOLD分级）：\n  GOLD 1级（轻度）：FEV1≥80%预计值\n  GOLD 2级（中度）：50%≤FEV1<80%预计值\n  GOLD 3级（重度）：30%≤FEV1<50%预计值\n  GOLD 4级（极重度）：FEV1<30%预计值\n\n4.2 影像学检查\n- 胸部X线：可见肺过度充气征象，如肺透亮度增加、横膈低平\n- 胸部CT：可发现肺气肿、支气管壁增厚等改变\n- CT检查有助于鉴别诊断和评估合并症','file_20_chunk_1','2026-08-12 15:38:08'),
(49,20,2,'4.3 实验室检查\n- 血常规：急性加重时白细胞和中性粒细胞可升高\n- 动脉血气分析：评估呼吸衰竭程度\n- 血清α1-抗胰蛋白酶水平：45岁以下发病者应筛查\n\n五、稳定期治疗\n\n5.1 药物治疗\n（1）支气管舒张剂（核心治疗药物）\n- 短效β2受体激动剂（SABA）：沙丁胺醇，按需使用\n- 短效抗胆碱能药物（SAMA）：异丙托溴铵\n- 长效β2受体激动剂（LABA）：沙美特罗、福莫特罗、茚达特罗\n- 长效抗胆碱能药物（LAMA）：噻托溴铵、格隆溴铵、乌美溴铵\n- LABA+LAMA联合制剂：茚达特罗/格隆溴铵、维兰特罗/乌美溴铵\n\n（2）吸入性糖皮质激素（ICS）\n- 适用于血嗜酸性粒细胞≥300/μL或频繁急性加重的患者\n- 常用ICS+LABA联合制剂：布地奈德/福莫特罗、氟替卡松/沙美特罗\n- 三联疗法（ICS+LABA+LAMA）：适用于中重度患者\n\n（3）其他药物\n- 磷酸二酯酶-4（PDE4）抑制剂：罗氟司特\n- 黏液溶解剂：N-乙酰半胱氨酸、羧甲司坦\n- 大环内酯类抗生素：阿奇霉素（长期低剂量）','file_20_chunk_2','2026-08-12 15:38:08'),
(50,20,3,'（3）其他药物\n- 磷酸二酯酶-4（PDE4）抑制剂：罗氟司特\n- 黏液溶解剂：N-乙酰半胱氨酸、羧甲司坦\n- 大环内酯类抗生素：阿奇霉素（长期低剂量）\n\n5.2 非药物治疗\n- 肺康复：包括运动训练、呼吸训练、营养支持、心理辅导\n- 长期氧疗（LTOT）：PaO2≤55mmHg或SaO2≤88%时\n- 无创正压通气（NPPV）：合并高碳酸血症的患者\n- 外科治疗：肺减容术、肺大疱切除术、肺移植\n\n六、急性加重的管理\n\n急性加重定义：呼吸道症状的急性恶化，需要额外治疗。\n\n治疗措施：\n1. 增加短效支气管舒张剂的使用频率和剂量\n2. 全身性糖皮质激素：泼尼松30-40mg/日，疗程5-7天\n3. 抗生素：适用于痰量增多且痰变脓性时\n   - 推荐药物：阿莫西林/克拉维酸、头孢类、左氧氟沙星\n4. 氧疗：目标SpO2 88-92%\n5. 无创机械通气：pH<7.35且PaCO2>45mmHg时考虑\n6. 有创机械通气：无创通气失败或存在严重呼吸衰竭时\n\n七、预防措施','file_20_chunk_3','2026-08-12 15:38:08'),
(51,20,4,'七、预防措施\n\n1. 戒烟：最重要和最有效的干预措施\n2. 疫苗接种：每年接种流感疫苗，接种肺炎球菌疫苗\n3. 减少职业暴露\n4. 避免室内外空气污染\n5. 规律随访和自我管理教育\n\n参考文献：\n1. Global Initiative for Chronic Obstructive Lung Disease (GOLD) 2024 Report\n2. 慢性阻塞性肺疾病诊治指南（2021年修订版），中华医学会呼吸病学分会\n3. NICE Guideline: Chronic obstructive pulmonary disease in over 16s (2024 update)','file_20_chunk_4','2026-08-12 15:38:08'),
(52,21,0,'阿莫西林药物说明书\n一、药物概述\n阿莫西林（Amoxicillin）是一种广谱半合成青霉素类β-内酰胺抗生素，由英国比彻姆公司于1972\n年开发上市。\n通用名：阿莫西林\n英文名：Amoxicillin\n化学式：C16H19N3O5S\n分子量：365.4 g/mol\n剂型：胶囊（250mg、500mg）、片剂、颗粒剂、干混悬剂\n二、药理作用\n阿莫西林通过抑制细菌细胞壁合成发挥杀菌作用。其机制为：与细菌细胞膜上的青霉素结合蛋白（P\nBPs）结合，抑制转肽酶的活性，阻碍细胞壁黏肽的交叉联接，使细菌细胞壁合成受阻，菌体膨胀裂\n解而死亡。\n药代动力学特点：\n- 口服吸收良好，生物利用度约75-90%，不受食物影响\n- 血浆蛋白结合率约20%\n- 广泛分布于体液和组织，可透过胎盘\n- 半衰期约1-1.5小时\n- 主要经肾脏排泄（60-70%以原形排出）\n三、抗菌谱\n阿莫西林对以下细菌有效：\n革兰阳性菌：\n- 链球菌属（包括肺炎链球菌、化脓性链球菌）\n- 不产β-内酰胺酶的葡萄球菌\n- 粪肠球菌\n- 李斯特菌\n革兰阴性菌：','file_21_chunk_0','2026-08-12 15:38:34'),
(53,21,1,'- 流感嗜血杆菌（不产β-内酰胺酶株）\n- 大肠埃希菌（部分菌株）\n- 奇异变形杆菌\n- 淋病奈瑟菌\n- 幽门螺杆菌\n天然耐药菌：\n- 产β-内酰胺酶的金黄色葡萄球菌\n- 铜绿假单胞菌\n- 肠杆菌属\n- 不动杆菌属\n四、适应证\n1. 上呼吸道感染：急性咽炎、扁桃体炎、中耳炎、鼻窦炎\n2. 下呼吸道感染：急性支气管炎、社区获得性肺炎（轻症）\n3. 泌尿生殖系统感染：尿路感染、淋病（单次大剂量）\n4. 皮肤软组织感染：蜂窝织炎、脓疱疮\n5. 幽门螺杆菌感染：作为根除Hp三联/四联方案中的核心药物\n6. 心内膜炎预防：牙科手术前预防感染性心内膜炎\n7. 莱姆病：早期莱姆病的一线治疗\n五、用法用量\n成人常用剂量：\n- 轻中度感染：250-500mg，每8小时一次\n- 重度感染：500mg-1g，每8小时一次\n- 幽门螺杆菌根除：1g，每日2次（联合其他药物，疗程14天）\n- 心内膜炎预防：术前1小时口服2g\n儿童常用剂量：\n- 轻中度感染：20-40mg/kg/日，分3次\n- 重度感染：40-90mg/kg/日，分2-3次\n- 中耳炎（大剂量方案）：80-90mg/kg/日，分2次','file_21_chunk_1','2026-08-12 15:38:34'),
(54,21,2,'- 重度感染：40-90mg/kg/日，分2-3次\n- 中耳炎（大剂量方案）：80-90mg/kg/日，分2次\n肾功能不全剂量调整：','file_21_chunk_2','2026-08-12 15:38:34'),
(55,21,3,'- GFR 10-30 ml/min：每12小时给药\n- GFR <10 ml/min：每24小时给药\n六、不良反应\n常见（1-10%）：腹泻、恶心、皮疹\n少见（0.1-1%）：呕吐、荨麻疹、腹痛\n罕见（<0.1%）：过敏性休克、Stevens-Johnson综合征、伪膜性肠炎、血液系统异常（白细胞减少\n、血小板减少）、肝功能异常、间质性肾炎\n特别警告：青霉素过敏者禁用。用药前应详细询问过敏史，必要时做皮肤过敏试验。一旦出现过敏\n反应立即停药并给予相应处理。\n七、注意事项\n1. 青霉素过敏者禁用，头孢菌素过敏者慎用（交叉过敏率约1-10%）\n2. 传染性单核细胞增多症患者使用可能出现皮疹（发生率高达90%），应避免使用\n3. 长期或反复使用可能导致二重感染（真菌感染或耐药菌感染）\n4. 妊娠期用药分类B级，必要时可使用\n5. 可分泌入乳汁，哺乳期使用需注意观察婴儿是否有腹泻或过敏\n6. 与甲氨蝶呤合用可增加甲氨蝶呤毒性\n7. 可能干扰口服避孕药的效果','file_21_chunk_3','2026-08-12 15:38:34'),
(56,22,0,'# 阿司匹林（Aspirin）药物说明书\n\n## 基本信息\n\n- **通用名称**：阿司匹林（乙酰水杨酸）\n- **英文名称**：Aspirin (Acetylsalicylic Acid)\n- **药物分类**：非甾体抗炎药（NSAID）/ 抗血小板药\n- **化学式**：C₉H₈O₄\n- **分子量**：180.16 g/mol\n- **CAS号**：50-78-2\n\n## 药理作用\n\n阿司匹林通过不可逆地抑制环氧化酶（COX）发挥作用：\n\n1. **抗血小板作用（低剂量75-150mg）**：不可逆抑制血小板COX-1，减少血栓素A2（TXA2）的生成，抑制血小板聚集。由于血小板无细胞核，不能重新合成COX，因此抑制作用持续血小板的整个生命周期（7-10天）。\n\n2. **解热镇痛抗炎作用（中高剂量300-1000mg）**：抑制前列腺素的合成，减少炎症介质的产生，发挥解热、镇痛和抗炎作用。\n\n## 适应证','file_22_chunk_0','2026-08-12 15:38:40'),
(57,22,1,'2. **解热镇痛抗炎作用（中高剂量300-1000mg）**：抑制前列腺素的合成，减少炎症介质的产生，发挥解热、镇痛和抗炎作用。\n\n## 适应证\n\n### 心血管适应证（低剂量）\n- 急性冠脉综合征（ACS）的一级和二级预防\n- 急性心肌梗死\n- 经皮冠状动脉介入治疗（PCI）术后\n- 缺血性卒中和短暂性脑缺血发作（TIA）的二级预防\n- 外周动脉疾病\n- 心房颤动患者不能使用口服抗凝药时的替代治疗\n\n### 解热镇痛适应证（中高剂量）\n- 发热\n- 头痛、牙痛、肌肉痛\n- 类风湿性关节炎\n- 骨关节炎\n- 强直性脊柱炎\n- 痛风性关节炎急性发作\n\n## 用法用量','file_22_chunk_1','2026-08-12 15:38:40'),
(58,22,2,'## 用法用量\n\n| 适应证 | 剂量 | 频次 |\n|--------|------|------|\n| 抗血小板（长期预防） | 75-100mg | 每日一次 |\n| 急性心肌梗死 | 首次300mg嚼服 | 之后75-100mg/日 |\n| PCI术后 | 100mg | 每日一次 |\n| 解热镇痛 | 300-600mg | 每4-6小时，最大4g/日 |\n| 类风湿性关节炎 | 3-5g/日 | 分3-4次 |\n| 川崎病 | 急性期30-50mg/kg/日 | 恢复期3-5mg/kg/日 |\n\n## 不良反应\n\n### 常见不良反应\n- 胃肠道反应：恶心、呕吐、上腹部不适、胃灼热\n- 消化道出血：黑便、呕血（发生率约1-2%/年）\n\n### 少见不良反应\n- 过敏反应：荨麻疹、血管性水肿、支气管痉挛（阿司匹林哮喘）\n- 出血倾向：皮肤瘀斑、牙龈出血\n- 肝肾功能损害\n- Reye综合征（儿童病毒感染期间使用）\n\n## 禁忌证','file_22_chunk_2','2026-08-12 15:38:40'),
(59,22,3,'## 禁忌证\n\n1. 对阿司匹林或其他水杨酸类药物过敏\n2. 活动性消化道溃疡或出血\n3. 严重肝肾功能不全\n4. 出血性疾病（血友病、血小板减少症）\n5. 妊娠晚期（第三个月）\n6. 16岁以下儿童病毒感染（Reye综合征风险）\n\n## 药物相互作用\n\n- **华法林**：增加出血风险\n- **布洛芬**：可能减弱阿司匹林的抗血小板作用\n- **甲氨蝶呤**：减少其肾脏排泄，增加毒性\n- **ACE抑制剂**：可能降低降压效果\n- **丙磺舒**：减弱其促尿酸排泄作用\n- **口服降糖药**：可能增强降糖作用\n\n## 注意事项\n\n1. 空腹时服用吸收更快，但为减少胃肠道刺激建议饭后服用\n2. 肠溶片应整片吞服，不要咀嚼或压碎\n3. 手术前7-10天应停用阿司匹林\n4. 长期使用者应定期检查血常规和粪便潜血\n5. 老年人应从低剂量开始\n6. 哺乳期妇女使用需权衡利弊\n\n## 贮藏\n\n密封，在干燥处保存，温度不超过25°C。\n\n## 参考文献','file_22_chunk_3','2026-08-12 15:38:40'),
(60,22,4,'## 贮藏\n\n密封，在干燥处保存，温度不超过25°C。\n\n## 参考文献\n\n1. Antithrombotic Trialists\' Collaboration. Aspirin in the primary and secondary prevention of vascular disease. Lancet. 2009\n2. 中国药典（2020年版）\n3. Patrono C, et al. Low-dose aspirin for the prevention of atherothrombosis. N Engl J Med. 2005','file_22_chunk_4','2026-08-12 15:38:40'),
(61,23,0,'奥美拉唑（Omeprazole）药物信息\n\n一、基本信息\n\n通用名：奥美拉唑\n英文名：Omeprazole\n商品名：洛赛克（Losec）、奥克（Aoke）等\n药物分类：质子泵抑制剂（PPI）\n化学式：C17H19N3O3S\n分子量：345.42 g/mol\n剂型：肠溶胶囊（10mg、20mg）、肠溶片、注射用粉剂（40mg）\n\n二、作用机制\n\n奥美拉唑是一种前药（prodrug），本身无活性。口服后在胃壁细胞分泌小管的酸性环境中（pH<4）转化为活性形式——次磺酰胺，与壁细胞H+/K+-ATP酶（质子泵）的半胱氨酸残基形成不可逆的共价键，使质子泵永久失活。\n\n每次给药可抑制约70%的质子泵。由于新的质子泵持续合成（半衰期约50小时），需连续给药2-5天才能达到最大抑酸效果。停药后抑酸作用可持续2-3天。\n\n奥美拉唑是目前最强效的抑酸药物之一，可将胃内pH升高至4以上长达16-18小时/天，使24小时胃酸分泌减少约80%。\n\n三、适应证\n\n1. 胃食管反流病（GERD）\n   - 糜烂性食管炎的初始治疗和维持治疗\n   - 非糜烂性反流病（NERD）的症状控制','file_23_chunk_0','2026-08-12 15:38:46'),
(62,23,1,'三、适应证\n\n1. 胃食管反流病（GERD）\n   - 糜烂性食管炎的初始治疗和维持治疗\n   - 非糜烂性反流病（NERD）的症状控制\n\n2. 消化性溃疡\n   - 胃溃疡：20mg/日，疗程6-8周\n   - 十二指肠溃疡：20mg/日，疗程4周\n   - NSAID相关溃疡的治疗和预防\n\n3. 幽门螺杆菌根除治疗\n   - 标准三联方案：奥美拉唑 + 克拉霉素 + 阿莫西林（或甲硝唑）\n   - 铋剂四联方案：奥美拉唑 + 铋剂 + 两种抗生素\n   - 剂量：20mg，每日2次，疗程14天\n\n4. 卓-艾综合征（胃泌素瘤）\n   - 起始剂量：60mg/日\n   - 根据症状和胃酸分泌调整，可达120mg/日\n\n5. 应激性溃疡的预防\n   - ICU重症患者的预防性用药\n   - 注射剂：40mg静脉滴注，每12小时一次\n\n6. 上消化道出血\n   - 大剂量方案：80mg静脉推注后，8mg/h持续泵入72小时\n\n四、用法用量','file_23_chunk_1','2026-08-12 15:38:46'),
(63,23,2,'6. 上消化道出血\n   - 大剂量方案：80mg静脉推注后，8mg/h持续泵入72小时\n\n四、用法用量\n\n口服：\n- 成人常规剂量：20mg，每日1次，晨起空腹服用\n- 重症或疗效不佳：20mg，每日2次或40mg每日1次\n- 维持治疗：10-20mg/日\n\n注射：\n- 静脉注射/滴注：40mg，每12小时一次\n- 上消化道出血：80mg负荷量后8mg/h持续泵入\n\n特殊人群：\n- 老年人：一般无需调整剂量\n- 肝功能不全：每日剂量不超过20mg\n- 肾功能不全：无需调整剂量\n- 妊娠期：C类，权衡利弊后使用\n\n给药提示：\n- 餐前30-60分钟服用效果最佳\n- 肠溶胶囊/片应整粒吞服，不可咀嚼或压碎\n- 与食物同服不影响疗效但会延迟达峰时间\n\n五、不良反应\n\n常见（发生率1-10%）：\n- 头痛（约7%）\n- 腹泻（约3%）\n- 腹痛（约3%）\n- 恶心（约2%）\n- 头晕、口干、便秘','file_23_chunk_2','2026-08-12 15:38:46'),
(64,23,3,'五、不良反应\n\n常见（发生率1-10%）：\n- 头痛（约7%）\n- 腹泻（约3%）\n- 腹痛（约3%）\n- 恶心（约2%）\n- 头晕、口干、便秘\n\n长期使用的潜在风险（>1年）：\n1. 低镁血症：长期使用可导致血镁降低，表现为肌肉痉挛、心律失常\n2. 骨质疏松和骨折风险增加：尤其是髋部骨折，FDA已发出警告\n3. 维生素B12吸收减少\n4. 铁吸收减少\n5. 难辨梭菌感染（CDI）风险增加\n6. 社区获得性肺炎风险轻度增加\n7. 肾脏损害：急性间质性肾炎、慢性肾病风险\n\n六、药物相互作用\n\n1. 氯吡格雷：奥美拉唑通过抑制CYP2C19降低氯吡格雷的活性代谢产物浓度，可能减弱抗血小板效果。建议改用泮托拉唑或雷贝拉唑。\n\n2. 甲氨蝶呤：PPI可减少甲氨蝶呤的肾清除，增加毒性风险\n\n3. 地高辛：胃酸pH升高可增加地高辛吸收，需监测血药浓度\n\n4. 抗真菌药（酮康唑、伊曲康唑）：胃酸减少影响其吸收，降低疗效\n\n5. 阿扎那韦等HIV蛋白酶抑制剂：PPI显著降低其吸收，不建议联用\n\n6. 铁剂：胃酸减少影响铁的吸收\n\n七、注意事项','file_23_chunk_3','2026-08-12 15:38:46'),
(65,23,4,'5. 阿扎那韦等HIV蛋白酶抑制剂：PPI显著降低其吸收，不建议联用\n\n6. 铁剂：胃酸减少影响铁的吸收\n\n七、注意事项\n\n1. 使用PPI前应排除胃癌等恶性疾病，因PPI可掩盖症状延误诊断\n2. 尽可能使用最低有效剂量和最短疗程\n3. 长期使用者应定期评估是否仍需继续治疗\n4. 长期使用者建议监测血镁、维生素B12水平\n5. 突然停药可能出现反跳性胃酸分泌增多，建议逐步减量\n6. 肝功能不全者慎用，需减量\n7. 可能影响尿蛋白定性试验结果\n\n八、贮藏\n\n遮光、密封，25°C以下保存。注射用粉剂溶解后应在4小时内使用。','file_23_chunk_4','2026-08-12 15:38:46'),
(66,23,5,'八、贮藏\n\n遮光、密封，25°C以下保存。注射用粉剂溶解后应在4小时内使用。\n\n参考文献：\n1. 中华医学会消化病学分会. 胃食管反流病诊治指南（2020年修订版）\n2. Wolfe MM, Sachs G. Acid suppression: optimizing therapy for GERD. Gastroenterology. 2000\n3. FDA Drug Safety Communication: Possible increased risk of fractures with PPI use (2010, updated 2011)','file_23_chunk_5','2026-08-12 15:38:46'),
(67,24,0,'盐酸二甲双胍药物信息手册\n一、药物概述\n二甲双胍（Metformin）是双胍类口服降血糖药物，自1957年上市以来一直是2型糖尿病治疗的基石药物。在所有国际和国内糖尿病管理指南中，二甲双胍均被推荐为2型糖尿病的一线首选用药。\n通用名称：盐酸二甲双胍\n英文名称：Metformin Hydrochloride\n化学式：C4H11N5·HCl\n分子量：165.63 g/mol\n剂型：普通片剂（250mg、500mg、850mg）、缓释片（500mg）、口服溶液\n二、作用机制\n二甲双胍通过多种途径发挥降糖作用：\n1. 抑制肝糖输出：激活AMPK（腺苷酸活化蛋白激酶），抑制肝脏糖异生，减少肝糖原分解，降低肝脏葡萄糖输出（主要降糖机制，可减少肝糖输出约25-30%）\n2. 增加外周组织对葡萄糖的摄取和利用：改善骨骼肌、脂肪组织的胰岛素敏感性，促进葡萄糖转运体GLUT4转位至细胞膜\n3. 抑制肠道葡萄糖吸收：延缓肠道对葡萄糖的吸收\n4. 改善脂代谢：降低血浆游离脂肪酸和甘油三酯水平\n重要特点：二甲双胍单独使用不会引起低血糖，因为它不刺激胰岛素分泌，而是通过改善胰岛素敏感性发挥作用。\n三、适应证','file_24_chunk_0','2026-08-12 15:38:51'),
(68,24,1,'重要特点：二甲双胍单独使用不会引起低血糖，因为它不刺激胰岛素分泌，而是通过改善胰岛素敏感性发挥作用。\n三、适应证\n1. 2型糖尿病：一线首选药物，可单独使用或与其他降糖药联合使用\n2. 糖尿病前期（IFG或IGT）：用于生活方式干预后血糖仍不达标者\n3. 多囊卵巢综合征（PCOS）：改善胰岛素抵抗和排卵功能（超说明书用药）\n4. 妊娠期糖尿病：部分指南推荐可用于胰岛素替代（需谨慎）\n探索中的适应证：\n- 抗肿瘤（乳腺癌、结直肠癌等的辅助治疗）\n- 抗衰老\n- 非酒精性脂肪肝病（NAFLD）\n四、用法用量\n起始剂量与剂量调整：\n- 起始剂量：500mg，每日1-2次，随餐服用\n- 每1-2周增加500mg，逐步滴定至有效剂量\n- 常用维持剂量：1500-2000mg/日，分2-3次\n- 最大推荐剂量：2550mg/日\n- 缓释片：起始500mg，每日一次（晚餐时），最大2000mg/日\n特殊人群剂量调整：\n- 老年人（≥65岁）：从最低剂量开始，根据肾功能调整\n- 肾功能不全：\n  eGFR 45-60 ml/min/1.73m²：最大剂量1000mg/日','file_24_chunk_1','2026-08-12 15:38:51'),
(69,24,2,'- 老年人（≥65岁）：从最低剂量开始，根据肾功能调整\n- 肾功能不全：\n  eGFR 45-60 ml/min/1.73m²：最大剂量1000mg/日\n  eGFR 30-45 ml/min/1.73m²：最大剂量500mg/日\n  eGFR <30 ml/min/1.73m²：禁用\n- 肝功能不全：严重肝功能不全禁用\n服药提示：\n- 随餐或餐后立即服用，减少胃肠道不良反应\n- 缓释片应整片吞服，不可掰碎或嚼碎\n- 如漏服一次，不要在下次服药时加倍剂量\n五、不良反应与处理\n常见不良反应（发生率>10%）：\n1. 胃肠道反应：腹泻（约30%）、恶心呕吐（约25%）、腹胀、腹痛、食欲减退\n   - 处理：从低剂量开始，逐渐增加；随餐服用；改用缓释片\n   - 多数患者在使用数周后症状可自行缓解\n2. 金属味觉：口中有金属味感\n少见但严重不良反应：\n1. 乳酸酸中毒（发生率约3-10/100,000人年）\n   - 表现：恶心呕吐、腹痛、过度换气、嗜睡、低血压\n   - 危险因素：肾功能不全、肝功能不全、酗酒、脱水、休克、大手术、碘造影剂使用\n   - 处理：立即停药，对症支持治疗','file_24_chunk_2','2026-08-12 15:38:51'),
(70,24,3,'- 危险因素：肾功能不全、肝功能不全、酗酒、脱水、休克、大手术、碘造影剂使用\n   - 处理：立即停药，对症支持治疗\n2. 维生素B12缺乏（长期使用，发生率5-10%）\n   - 建议长期使用者定期检测维生素B12水平\n   - 必要时补充维生素B12\n六、药物相互作用\n1. 碘造影剂：使用碘造影剂前48小时和后48小时应停用二甲双胍，以防乳酸酸中毒\n2. 酒精：增加乳酸酸中毒风险，应避免大量饮酒\n3. 西咪替丁：抑制二甲双胍的肾小管分泌，使其血药浓度升高\n4. 糖皮质激素：对抗二甲双胍的降糖作用\n5. 利尿剂：可能加重肾功能损害和脱水\n6. SGLT2抑制剂、GLP-1受体激动剂：可安全联合使用\n7. 胰岛素：联合使用时注意低血糖风险\n七、临床优势\n1. 确切的降糖效果：单药可降低HbA1c 1.0-1.5%\n2. 不增加体重，甚至可能减轻体重\n3. 单独使用不引起低血糖\n4. 心血管获益：UKPDS研究证实可减少心血管事件和死亡率\n5. 价格低廉，可及性好\n6. 安全性良好，临床使用经验丰富（超过60年）\n7. 可能具有潜在的抗肿瘤和抗衰老作用','file_24_chunk_3','2026-08-12 15:38:51');

/*Table structure for table `t_knowledge_file` */

DROP TABLE IF EXISTS `t_knowledge_file`;

CREATE TABLE `t_knowledge_file` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件名',
  `file_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件类型:txt/doc/pdf/markdown',
  `file_size` bigint DEFAULT '0' COMMENT '文件大小(字节)',
  `file_path` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '存储路径',
  `chunk_count` int DEFAULT '0' COMMENT '分块数量',
  `vector_status` tinyint DEFAULT '0' COMMENT '向量化状态:0待处理1处理中2已完成3失败',
  `upload_by` int DEFAULT NULL COMMENT '上传人ID',
  `upload_role` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'admin' COMMENT '上传人角色',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='知识库文件表';

